#!/usr/bin/env python3
import base64
import os
import sys

def find_file(filename):
    for root, dirs, files in os.walk('.'):
        if 'build' in root.split(os.sep):
            continue
        if filename in files:
            return os.path.join(root, filename)
    return None

def find_res_dir():
    manifest = find_file('AndroidManifest.xml')
    if manifest:
        candidate = os.path.join(os.path.dirname(manifest), 'res')
        if os.path.isdir(candidate):
            return candidate
    for root, dirs, files in os.walk('.'):
        if 'build' in root.split(os.sep):
            continue
        if os.path.basename(root) == 'res' and 'main' in root.split(os.sep):
            return root
    return os.path.join('app', 'src', 'main', 'res')

