if __name__ == '__main__':
    for fname, content in TEXT_FILES.items():
        path = find_file(fname)
        if not path:
            print(f'[VIRHE] Tiedostoa {fname} ei löytynyt!')
            sys.exit(1)
        with open(path, 'w', encoding='utf-8') as f:
            f.write(content)
        print(f'[OK] Päivitetty: {path}')

    res_dir = find_res_dir()
    os.makedirs(res_dir, exist_ok=True)

    for rel_path, content in RES_TEXT_FILES.items():
        full_path = os.path.join(res_dir, *rel_path.split('/'))
        os.makedirs(os.path.dirname(full_path), exist_ok=True)
        with open(full_path, 'w', encoding='utf-8') as f:
            f.write(content)
        print(f'[OK] Kirjoitettu resurssi: {full_path}')

    for rel_path, b64_data in RES_PNG_B64.items():
        full_path = os.path.join(res_dir, *rel_path.split('/'))
        os.makedirs(os.path.dirname(full_path), exist_ok=True)
        with open(full_path, 'wb') as f:
            f.write(base64.b64decode(b64_data))
        print(f'[OK] Kirjoitettu kuvaresurssi: {full_path}')
